const body = $json.body || {};
const sender = body.sender || {};
const requestReceivedAtMs = Date.now();
const conversationId = body.conversation_id || body.thread_id || sender.id || 'unknown-conversation';
const messageId = body.message_id || body.mid || `${conversationId}:${requestReceivedAtMs}`;
return [{ json: { conversation_id: conversationId, user_id: sender.id || null, message_id: messageId, message_text: (body.message || body.text || '').toString().trim(), request_received_at_ms: requestReceivedAtMs } }];

const e = $json || {};
const make = e.make || null;
const model = e.model || null;
const year = e.year ? parseInt(String(e.year).replace(/[^0-9]/g, ''), 10) : null;
const category = e.category || null;
let stage = 'recommend';
let prompt = null;
if (!make) { stage = 'ask_make'; prompt = 'Necesito la marca de tu vehiculo.'; }
else if (!model) { stage = 'ask_model'; prompt = 'Necesito el modelo del vehiculo.'; }
else if (!year) { stage = 'ask_year'; prompt = 'Necesito el ano del vehiculo.'; }
else if (!category) { stage = 'ask_category'; prompt = 'Que categoria buscas?'; }
return [{ json: { ...$node['Normalize Payload'].json, make, model, year, category, stage, stage_prompt: prompt, slots_complete: stage === 'recommend', query_embedding: e.query_embedding || null } }];

const row = $json || {};
const state = $node['Resolve Stage'].json;
const startedAt = Number(state.request_received_at_ms || Date.now());
const technicalLatencyMs = Math.max(0, Date.now() - startedAt);
let response = state.stage_prompt || '';
let eventType = 'state_update';
let errorCode = null;
if (state.stage === 'recommend') {
  eventType = 'recommendation';
  if (!row.product_sku) { response = 'No encuentro compatibilidad confirmada. Te paso con un asesor humano.'; eventType = 'handoff'; errorCode = 'NO_SQL_FIT'; }
  else if (!row.snapshot_id || Number(row.snapshot_age_minutes || 9999) > 1440 || String(row.stock_status || '').toLowerCase().includes('out')) { response = 'Tengo compatibilidad, pero stock/precio no estan confirmados en tiempo real. Te conecto con un asesor.'; eventType = 'handoff'; errorCode = 'STOCK_UNCONFIRMED'; }
  else if (!row.source_ref) { response = 'No tengo evidencia tecnica trazable para responder con seguridad. Te conecto con un asesor.'; eventType = 'handoff'; errorCode = 'LOW_TECH_EVIDENCE'; }
  else { response = `SKU ${row.product_sku}, precio ${row.price_amount || 'no confirmado'} ${row.currency || ''}, stock ${row.stock_status || 'no confirmado'}. Fuente tecnica: ${row.source_ref}.`; }
}
return [{ json: { ...state, formatted_response: response, event_type: eventType, source_ref: row.source_ref || null, snapshot_version: row.snapshot_id || null, technical_latency_ms: state.stage === 'recommend' ? technicalLatencyMs : null, error_code: errorCode } }];
